args.newString:
import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'
import { CardStatsSkeleton } from './CardStats'

async function getDashboardData() {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

function RevenueChartWrapper() {
  return import('./RevenueChart').then(({ RevenueChart }) => {
    return RevenueChart({ revenue: [] })
  })
}

function LatestInvoicesWrapper() {
  return import('./LatestInvoices').then(({ LatestInvoices }) => {
    return LatestInvoices({ invoices: [] })
  })
}

export default async function Page() {
  const data = await getDashboardData()

  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <CardStats
          totalRevenue={data.totalRevenue}
          totalInvoices={data.totalInvoices}
        />
      </Suspense>
      <Suspense fallback={<div className="chart skeleton">Loading chart...</div>}>
        <RevenueChartWrapper />
      </Suspense>
      <Suspense fallback={<div className="invoices skeleton">Loading invoices...</div>}>
        <LatestInvoicesWrapper />
      </Suspense>
    </main>
  )
}

